head.b:skin:
:root{--navy:#102a43;--blue:#2463eb;--teal:#14b8a6;--ink:#172b3a;--muted:#617487;--paper:#f4f7fb;--card:#fff;--line:#e4ebf2;--soft:#eaf2ff;--shadow:0 14px 38px rgba(16,42,67,.08);--radius:19px}
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:90px}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.7 'DM Sans',Arial,sans-serif;-webkit-font-smoothing:antialiased}body.dark{--paper:#0b1420;--card:#111f2e;--ink:#e8f0f7;--muted:#a4b4c4;--line:#26384a;--soft:#172c43;--shadow:0 14px 38px rgba(0,0,0,.24)}a{color:var(--blue);text-decoration:none}a:hover{text-decoration:underline}img{max-width:100%;height:auto}button,input{font:inherit}.skip{position:absolute;left:-9999px;top:8px;z-index:999;background:var(--card);padding:10px}.skip:focus{left:10px}.shell{max-width:1160px;margin:auto;padding:0 22px}.topline{background:var(--navy);color:#dbeafe;font-size:12px}.topline .shell{display:flex;justify-content:space-between;padding:7px 22px}.topline a{color:#fff}.sitehead{position:sticky;top:0;z-index:100;background:color-mix(in srgb,var(--card) 93%,transparent);backdrop-filter:blur(16px);border-bottom:1px solid var(--line)}.headin{min-height:78px;display:flex;align-items:center;justify-content:space-between;gap:18px}.brand{display:flex;align-items:center;gap:11px;color:var(--ink)}.mark{width:43px;height:43px;border-radius:14px;background:linear-gradient(135deg,var(--blue),var(--teal));display:grid;place-items:center;color:white;font-weight:800}.brand strong{display:block;font:800 18px Manrope,sans-serif;line-height:1.2}.brand small{display:block;color:var(--muted);font-size:10px;margin-top:4px}.nav{display:flex;gap:5px;align-items:center}.nav a,.action{padding:9px 12px;border:0;border-radius:11px;background:none;color:var(--ink);font-size:13px;font-weight:800;cursor:pointer}.nav a:hover,.action:hover{background:var(--soft);text-decoration:none}.actions{display:flex;gap:7px}.iconbtn{width:41px;height:41px;border:1px solid var(--line);border-radius:12px;background:var(--card);color:var(--ink);cursor:pointer;font-size:18px}.menu-btn{display:none}.hero{padding:58px 0 45px;background:radial-gradient(circle at 85% 15%,rgba(20,184,166,.16),transparent 27%),radial-gradient(circle at 10% 5%,rgba(36,99,235,.13),transparent 30%)}.hero-grid{display:grid;grid-template-columns:1.3fr .7fr;align-items:center;gap:36px}.eyebrow{display:inline-block;padding:6px 12px;border-radius:99px;background:var(--soft);color:var(--blue);font-size:11px;font-weight:800;letter-spacing:.6px;text-transform:uppercase}.hero h1{font:800 clamp(35px,5vw,56px)/1.08 Manrope,sans-serif;letter-spacing:-1.8px;color:var(--navy);margin:18px 0}.dark .hero h1{color:#edf6ff}.hero p{max-width:690px;color:var(--muted);font-size:17px;margin:0 0 23px}.btn{display:inline-flex;padding:11px 17px;border-radius:12px;background:var(--blue);color:white;font-weight:800;margin:3px 6px 3px 0}.btn:hover{color:white;text-decoration:none}.btn.alt{background:var(--card);color:var(--ink);border:1px solid var(--line)}.hero-card,.project,.value-card,.widget,.post-outer,.post-outer-container{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow)}.hero-card{padding:23px}.hero-card small{color:var(--teal);font-weight:800;letter-spacing:1px;text-transform:uppercase}.hero-card h2{font:800 22px Manrope,sans-serif;margin:9px 0}.hero-card p{font-size:14px;margin:0;color:var(--muted)}.checks{display:grid;gap:9px;margin-top:16px;font-weight:700;font-size:13px}.checks span:before{content:'✓';color:var(--teal);font-weight:900;margin-right:9px}.section{padding:40px 0}.section-title{margin:0 0 5px;font:800 clamp(24px,3vw,31px) Manrope,sans-serif}.section-sub{margin:0 0 20px;color:var(--muted)}.projects{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.project{padding:21px;display:flex;gap:15px}.project .symbol{width:45px;height:45px;flex:0 0 45px;display:grid;place-items:center;border-radius:14px;background:var(--soft);font-size:21px}.project h3{font:800 17px Manrope,sans-serif;margin:0 0 5px}.project p{font-size:13px;color:var(--muted);margin:0 0 8px}.project a{font-weight:800;font-size:13px}.values{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.value-card{padding:16px}.value-card strong{font:800 14px Manrope,sans-serif;display:block}.value-card p{font-size:12px;color:var(--muted);margin:6px 0 0}.layout{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:26px;padding-top:25px;padding-bottom:48px}.column{min-width:0}.widget{padding:18px;margin-bottom:16px}.widget h2,.widget h3,.widget .title{font:800 16px Manrope,sans-serif;margin:0 0 12px}.widget-content{font-size:14px;color:var(--muted)}.blog-posts .post-outer,.post-outer-container{padding:22px;margin:0 0 17px}.post-title,.post-title a{font:800 clamp(21px,3vw,28px)/1.25 Manrope,sans-serif;color:var(--ink)}.post-body{line-height:1.85;overflow-wrap:anywhere}.post-body img{border-radius:13px}.post-body h2,.post-body h3{font-family:Manrope,sans-serif;line-height:1.3}.post-body blockquote{border-left:4px solid var(--teal);padding:10px 16px;background:var(--soft);margin:18px 0}.post-footer,.post-header,.post-timestamp{font-size:12px;color:var(--muted)}.searchbox{display:flex;gap:7px}.searchbox input{width:100%;min-width:0;padding:10px;border:1px solid var(--line);border-radius:10px;background:var(--paper);color:var(--ink)}.searchbox button{border:0;border-radius:10px;background:var(--blue);color:#fff;padding:0 13px;font-weight:800}.blog-pager{display:flex;justify-content:space-between;gap:10px}.blog-pager a{padding:9px 13px;border:1px solid var(--line);border-radius:10px;background:var(--card)}.footer{background:#0b2033;color:#d8e5f0;padding:38px 0 90px}.footer-grid{display:grid;grid-template-columns:1.3fr 1fr 1fr;gap:25px}.footer h3{font:800 15px Manrope,sans-serif;color:#fff;margin:0 0 10px}.footer p,.footer li{font-size:12px;color:#b9c9d8}.footer ul{list-style:none;padding:0;margin:0}.footer li{margin:6px 0}.footer a{color:#dbeafe}.foot-bottom{border-top:1px solid #ffffff24;margin-top:24px;padding-top:15px;font-size:11px;color:#9fb2c5;display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap}.mobilebar{display:none}.totop{position:fixed;right:18px;bottom:20px;width:42px;height:42px;border:0;border-radius:13px;background:var(--navy);color:white;font-size:19px;z-index:80;cursor:pointer}
@media(max-width:900px){.hero-grid{grid-template-columns:1fr}.hero-card{max-width:600px}.layout{grid-template-columns:minmax(0,1fr) 250px}.values{grid-template-columns:repeat(2,1fr)}}
@media(max-width:700px){.shell{padding:0 15px}.topline .shell{justify-content:center;text-align:center}.topline .shell span:last-child{display:none}.headin{min-height:66px}.brand strong{font-size:16px}.brand small{font-size:9px}.nav{display:none;position:absolute;left:10px;right:10px;top:calc(100% + 7px);padding:10px;background:var(--card);border:1px solid var(--line);border-radius:15px;box-shadow:var(--shadow);flex-direction:column;align-items:stretch}.nav.open{display:flex}.nav a{padding:11px}.menu-btn{display:inline-grid;place-items:center}.hero{padding:38px 0 30px}.hero h1{letter-spacing:-1px}.hero p{font-size:15px}.hero-card{padding:19px}.section{padding:30px 0}.projects{grid-template-columns:1fr}.project{padding:17px}.layout{display:block;padding-top:15px}.sidebar-column{margin-top:18px}.blog-posts .post-outer,.post-outer-container{padding:17px}.footer-grid{grid-template-columns:1fr;gap:17px}.mobilebar{position:fixed;display:grid;grid-template-columns:repeat(4,1fr);left:9px;right:9px;bottom:max(9px,env(safe-area-inset-bottom));z-index:150;padding:6px;background:color-mix(in srgb,var(--card) 94%,transparent);backdrop-filter:blur(16px);border:1px solid var(--line);border-radius:17px;box-shadow:0 12px 30px #0002}.mobilebar a,.mobilebar button{border:0;background:none;color:var(--muted);display:flex;flex-direction:column;align-items:center;gap:1px;padding:4px;font-size:10px;font-weight:800}.mobilebar b{font-size:18px;color:var(--blue);line-height:1.2}.totop{right:14px;bottom:83px;width:37px;height:37px}}
@media(max-width:380px){.brand small{display:none}.values{grid-template-columns:1fr}.btn{width:100%;justify-content:center}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{transition:none!important;animation:none!important}}
